Load the cached values from the imported Data sheet, find the header row and all rows whose Column A text starts with `**`. Copy the header and each matching row up to its last non-empty cell into summary Limits, clearing the graded A1:D7 region first. Save the workbook with plain values.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

def find_sheet(wb_obj, name):
    target = name.strip().lower()
    for sheet_name in wb_obj.sheetnames:
        if sheet_name.strip().lower() == target:
            return sheet_name
    return None

src_name = find_sheet(vals, "imported Data")
if src_name is None:
    src_name = "imported Data"
src = vals[src_name]

dst_name = find_sheet(wb, "summary Limits")
if dst_name is None:
    dst_name = "summary Limits"
    ws = wb.create_sheet(dst_name)
else:
    ws = wb[dst_name]

# Clear the graded answer region before writing.
for r in range(1, 8):
    for c in range(1, 5):
        ws.cell(row=r, column=c).value = None

max_row = src.max_row
max_col = src.max_column

def get_row_values(row):
    return [src.cell(row=row, column=c).value for c in range(1, max_col + 1)]

def last_nonempty(values):
    last = 0
    for idx, value in enumerate(values, start=1):
        if value is None:
            continue
        if isinstance(value, str) and value.strip() == "":
            continue
        last = idx
    return last

def clean_value(value):
    if isinstance(value, str):
        return value.strip()
    return value

# Copy header row.
header_values = get_row_values(1)
header_last = last_nonempty(header_values)
if header_last == 0:
    header_last = 1

out_row = 1
for c in range(1, header_last + 1):
    ws.cell(row=out_row, column=c).value = clean_value(header_values[c - 1])
out_row += 1

# Copy matching rows.
matched_rows = 0
for r in range(2, max_row + 1):
    a_value = src.cell(row=r, column=1).value
    if isinstance(a_value, str) and a_value.startswith("**"):
        row_values = get_row_values(r)
        row_last = last_nonempty(row_values)
        if row_last == 0:
            row_last = 1

        for c in range(1, row_last + 1):
            ws.cell(row=out_row, column=c).value = clean_value(row_values[c - 1])

        out_row += 1
        matched_rows += 1

wb.save(OUT)

print("matched_rows:", matched_rows)
print("output_rows:", out_row - 1)
print("header_last_col:", header_last)
